<script>document.getElementById('accounting-report').addEventListener('submit',async function(e){e.preventDefault();const out=document.getElementById('accounting-report-result');out.textContent='Loading…';try{const r=await fetch(@json(route('extensions.accounting.reports',$business))+'?'+new URLSearchParams(new FormData(this)),{headers:{Accept:'application/json'}});const j=await r.json();if(!r.ok)throw Error(j.message||'Unable to load report');const d=j.data;out.replaceChildren();const money=v=>'₹'+(Number(v)/100).toFixed(2);const p=document.createElement('p');p.className='ex-output';p.textContent='Trial debit '+money(d.trial_debit_paise)+' · Trial credit '+money(d.trial_credit_paise)+'\nIncome '+money(d.income_paise)+' · Expenses '+money(d.expense_paise)+' · Profit '+money(d.profit_paise)+'\nCash in '+money(d.cash_in_paise)+' · Cash out '+money(d.cash_out_paise)+' · Net movement '+money(d.net_cash_movement_paise);out.append(p);const t=document.createElement('table');t.className='ex-table';const tr=t.insertRow();['Account','Opening','Debits','Credits','Closing'].forEach(v=>{const c=document.createElement('th');c.textContent=v;tr.append(c)});d.accounts.forEach(a=>{const row=t.insertRow();[a.code+' · '+a.name,money(a.opening_paise),money(a.debit_paise),money(a.credit_paise),money(a.closing_paise)].forEach(v=>row.insertCell().textContent=v)});out.append(t);}catch(err){out.textContent=err.message}});</script>
